"""Pendalaman matematis Tahap 1: penurunan rumus, sifat penaksir, dan soal tambahan."""
from .lengkap import D

D("dasar-jenis-data",
  [(r"Pendalaman: ketelitian sampel berlapis",
    [r"Ragam penaksir rata-rata berlapis adalah jumlah ragam rata-rata tiap lapisan yang ditimbang kuadrat bobotnya. Faktor \((1-f_h)\) dengan \(f_h=n_h/N_h\) adalah koreksi populasi terhingga; bila sampel kecil dibanding lapisannya, faktor ini mendekati 1.",
     r"Rumus ini menunjukkan mengapa pelapisan menguntungkan: keragaman antar lapisan tidak masuk ke ragam penaksir, yang tersisa hanya keragaman di dalam lapisan \(S_h^2\). Makin seragam isi tiap lapisan dan makin berbeda lapisan satu sama lain, makin besar keuntungannya. Alokasi Neyman \(n_h\propto N_hS_h\) memberi ragam terkecil untuk ukuran sampel tetap."],
    [r"\operatorname{Var}(\bar{y}_{st})=\sum_{h=1}^{H}W_h^2\,(1-f_h)\,\frac{S_h^2}{n_h},\qquad n_h^{\text{Neyman}}=n\,\frac{N_hS_h}{\sum_k N_kS_k}"]),
   (r"Pendalaman: efek rancangan pada sampel klaster",
    [r"Pada sampel klaster dengan \(m\) anggota per klaster, anggota klaster cenderung mirip; kemiripan ini diukur dengan korelasi intraklaster \(\rho\). Ragam penaksir naik sebesar efek rancangan (design effect, DEFF) dibanding sampel acak sederhana berukuran sama. Akibatnya ukuran sampel efektif lebih kecil dari jumlah responden.",
     r"Konsep yang sama muncul lagi pada rancangan percobaan: banyak tanaman dalam satu pot atau banyak hewan dalam satu kandang adalah klaster, sehingga memperlakukannya sebagai pengamatan bebas mengabaikan DEFF."],
    [r"\text{DEFF}=1+(m-1)\rho,\qquad n_{\text{efektif}}=\frac{n}{\text{DEFF}}"])],
  [(r"Survei 300 rumah tangga diambil dari 30 desa (10 rumah tangga per desa) dengan korelasi intraklaster \(\rho=0{,}05\). Berapa DEFF dan ukuran sampel efektifnya?",
    r"\(\text{DEFF}=1+9(0{,}05)=1{,}45\). Ukuran sampel efektif \(300/1{,}45\approx207\) rumah tangga."),
   (r"Dua lapisan berbobot \(W_1=0{,}6\) dan \(W_2=0{,}4\) dengan \(S_1=2\), \(S_2=5\), dan \(n_1=n_2=20\). Abaikan koreksi populasi terhingga. Hitung ragam rata-rata berlapis.",
    r"\(0{,}36(4/20)+0{,}16(25/20)=0{,}072+0{,}200=0{,}272\), sehingga galat bakunya \(\sqrt{0{,}272}=0{,}52\). Karena lapisan 2 lebih beragam, alokasi Neyman akan memberi lapisan 2 lebih banyak sampel.")])

D("dasar-statistik-deskriptif",
  [(r"Pendalaman: mengapa pembaginya n − 1",
    [r"Simpangan diukur terhadap \(\bar{x}\), bukan terhadap \(\mu\) yang tidak diketahui. Karena \(\bar{x}\) adalah titik yang meminimumkan jumlah kuadrat simpangan, jumlah kuadrat terhadap \(\bar{x}\) selalu lebih kecil daripada terhadap \(\mu\). Penurunan di bawah menunjukkan bahwa kekurangan itu tepat sebesar satu \(\sigma^2\) dalam nilai harapan, sehingga membagi dengan \(n-1\) menghasilkan penaksir tak bias.",
     r"Perhatikan bahwa \(s^2\) tak bias untuk \(\sigma^2\), tetapi \(s\) sedikit berbias ke bawah untuk \(\sigma\) karena akar adalah fungsi cekung. Pada sampel kecil bias ini kecil dan biasanya diabaikan."],
    [r"\sum_{i=1}^{n}(x_i-\bar{x})^2=\sum_{i=1}^{n}(x_i-\mu)^2-n(\bar{x}-\mu)^2",
     r"E\Big[\sum(x_i-\bar{x})^2\Big]=n\sigma^2-n\cdot\frac{\sigma^2}{n}=(n-1)\sigma^2\quad\Longrightarrow\quad E(s^2)=\sigma^2"]),
   (r"Pendalaman: ketaksamaan Chebyshev",
    [r"Aturan empiris 68–95–99,7% hanya berlaku untuk sebaran normal. Untuk sebaran apa pun yang ragamnya terhingga, ketaksamaan Chebyshev menjamin batas bawah proporsi data yang berada dalam \(k\) simpangan baku dari rata-rata. Batas ini longgar, tetapi tidak memerlukan asumsi bentuk sebaran sama sekali."],
    [r"P\big(|X-\mu|<k\sigma\big)\ \ge\ 1-\frac{1}{k^2},\qquad k>1"])],
  [(r"Menurut ketaksamaan Chebyshev, berapa proporsi minimal data yang berada dalam 2 simpangan baku dari rata-rata? Bandingkan dengan sebaran normal.",
    r"Minimal \(1-1/4=75\%\). Pada sebaran normal proporsinya sekitar 95%; Chebyshev memberi jaminan yang lebih lemah karena berlaku untuk semua sebaran."),
   (r"Tunjukkan bahwa \(\sum(x_i-\bar{x})=0\) untuk data apa pun.",
    r"\(\sum(x_i-\bar{x})=\sum x_i-n\bar{x}=\sum x_i-n\cdot\frac{1}{n}\sum x_i=0\). Karena itu satu simpangan selalu dapat dihitung dari yang lain, dan derajat bebasnya \(n-1\).")])

D("dasar-distribusi-normal",
  [(r"Pendalaman: nilai harapan dan ragam rata-rata sampel",
    [r"Dua sifat dasar nilai harapan dan ragam cukup untuk menurunkan galat baku: nilai harapan bersifat linear, dan ragam jumlah peubah yang saling bebas adalah jumlah ragamnya. Penurunan ini tidak memerlukan asumsi normal; kenormalan hanya dibutuhkan untuk bentuk sebarannya."],
    [r"E(\bar{X})=\frac{1}{n}\sum_{i=1}^{n}E(X_i)=\frac{1}{n}\,n\mu=\mu",
     r"\operatorname{Var}(\bar{X})=\frac{1}{n^2}\sum_{i=1}^{n}\operatorname{Var}(X_i)=\frac{1}{n^2}\,n\sigma^2=\frac{\sigma^2}{n}"]),
   (r"Pendalaman: fungsi pembangkit momen dan teorema limit pusat",
    [r"Fungsi pembangkit momen (FPM) \(M_X(t)=E(e^{tX})\) menentukan sebaran secara unik. Untuk normal, FPM-nya \(\exp(\mu t+\sigma^2t^2/2)\). FPM jumlah peubah saling bebas adalah hasil kali FPM-nya, sehingga jumlah normal juga normal.",
     r"Gagasan teorema limit pusat: FPM dari \(Z_n=\sqrt{n}(\bar{X}-\mu)/\sigma\) dapat diuraikan dengan deret Taylor; suku-suku orde tinggi mengecil ketika \(n\to\infty\), dan yang tersisa adalah \(e^{t^2/2}\), yaitu FPM normal baku."],
    [r"M_{Z_n}(t)=\Big[1+\frac{t^2}{2n}+o\!\left(\frac{1}{n}\right)\Big]^n\ \longrightarrow\ e^{t^2/2}\quad(n\to\infty)"])],
  [(r"\(X_1\sim N(10,\,3^2)\) dan \(X_2\sim N(15,\,4^2)\) saling bebas. Bagaimana sebaran \(X_1+X_2\), dan berapa \(P(X_1+X_2>30)\)?",
    r"\(X_1+X_2\sim N(25,\,3^2+4^2)=N(25,\,5^2)\). \(z=(30-25)/5=1\), sehingga \(P=0{,}1587\)."),
   (r"Mengapa ragam selisih dua peubah bebas adalah jumlah ragamnya, bukan selisihnya?",
    r"\(\operatorname{Var}(X_1-X_2)=\operatorname{Var}(X_1)+(-1)^2\operatorname{Var}(X_2)\). Konstanta pengali masuk sebagai kuadrat, sehingga tanda minus hilang; ketidakpastian dua pengukuran selalu bertambah.")])

D("dasar-uji-hipotesis",
  [(r"Pendalaman: penurunan rumus kuasa",
    [r"Untuk uji z dua arah dengan \(\sigma\) diketahui, \(H_0\) ditolak bila \(|\bar{X}-\mu_0|>z_{1-\alpha/2}\,\sigma/\sqrt{n}\). Bila rata-rata sebenarnya \(\mu_0+\delta\), statistik \(Z\) menyebar normal dengan rata-rata \(\delta\sqrt{n}/\sigma\). Kuasa adalah peluang \(Z\) jatuh di daerah penolakan di bawah sebaran itu.",
     r"Rumus ukuran sampel pada bagian sebelumnya diperoleh dengan mengabaikan suku kedua (yang sangat kecil) dan menyelesaikan persamaan kuasa \(=1-\beta\) untuk \(n\)."],
    [r"1-\beta=\Phi\!\left(\frac{\delta\sqrt{n}}{\sigma}-z_{1-\alpha/2}\right)+\Phi\!\left(-\frac{\delta\sqrt{n}}{\sigma}-z_{1-\alpha/2}\right)"]),
   (r"Pendalaman: uji rasio kemungkinan",
    [r"Banyak uji dibangun dari satu prinsip: membandingkan kemungkinan (likelihood) maksimum di bawah \(H_0\) dengan kemungkinan maksimum tanpa batasan. Lemma Neyman–Pearson menunjukkan bahwa untuk dua hipotesis sederhana, uji berdasarkan rasio ini adalah yang paling kuat pada taraf \(\alpha\) tertentu.",
     r"Untuk sampel besar, \(-2\ln\Lambda\) menyebar mendekati khi-kuadrat dengan derajat bebas sama dengan banyak parameter yang dibatasi (teorema Wilks). Uji t, uji F pada ANOVA dan regresi, serta uji deviance pada GLM semuanya merupakan bentuk uji rasio kemungkinan."],
    [r"\Lambda=\frac{\max_{\theta\in\Theta_0}L(\theta)}{\max_{\theta\in\Theta}L(\theta)},\qquad -2\ln\Lambda\ \xrightarrow{d}\ \chi^2_{q}"])],
  [(r"Uji dua arah pada \(\alpha=0{,}05\) dengan \(n=25\), \(\sigma=5\), dan beda sebenarnya \(\delta=2\). Berapa kuasanya?",
    r"\(\delta\sqrt{n}/\sigma=2(5)/5=2\). Kuasa \(=\Phi(2-1{,}96)+\Phi(-2-1{,}96)=\Phi(0{,}04)+\Phi(-3{,}96)\approx0{,}516\). Hanya sekitar 52%; percobaan ini kurang kuat untuk beda sebesar itu."),
   (r"Seorang peneliti menulis “P = 0,03 berarti peluang \(H_0\) benar hanya 3%”. Apa yang keliru?",
    r"P-value adalah peluang memperoleh data seekstrem itu atau lebih ekstrem bila \(H_0\) benar, \(P(\text{data}\mid H_0)\), bukan peluang \(H_0\) benar setelah melihat data, \(P(H_0\mid\text{data})\). Yang kedua memerlukan pendekatan Bayes dan peluang awal.")])

D("dasar-selang-kepercayaan",
  [(r"Pendalaman: membangun selang dari kuantitas pivot",
    [r"Kuantitas pivot adalah fungsi data dan parameter yang sebarannya tidak bergantung pada parameter apa pun. Untuk rata-rata populasi normal, \(T=(\bar{X}-\mu)/(S/\sqrt{n})\) menyebar \(t_{n-1}\) apa pun nilai \(\mu\) dan \(\sigma\). Pernyataan peluang tentang \(T\) lalu disusun ulang menjadi pernyataan tentang \(\mu\).",
     r"Cara yang sama menghasilkan selang untuk ragam (pivot khi-kuadrat), rasio dua ragam (pivot F), dan banyak parameter lain."],
    [r"P\!\left(-t_{\alpha/2}\le\frac{\bar{X}-\mu}{S/\sqrt{n}}\le t_{\alpha/2}\right)=1-\alpha\ \Longleftrightarrow\ P\!\left(\bar{X}-t_{\alpha/2}\frac{S}{\sqrt{n}}\le\mu\le\bar{X}+t_{\alpha/2}\frac{S}{\sqrt{n}}\right)=1-\alpha"]),
   (r"Pendalaman: ukuran sampel untuk galat batas dan selang simultan",
    [r"Lebar selang menyusut sebanding dengan \(1/\sqrt{n}\). Untuk mencapai galat batas \(E\), ukuran sampel yang diperlukan diperoleh dengan menyelesaikan \(z\sigma/\sqrt{n}=E\).",
     r"Bila beberapa selang dilaporkan bersama dan semuanya harus benar sekaligus, tingkat kepercayaan gabungannya lebih rendah daripada masing-masing. Koreksi Bonferroni membuat \(m\) selang masing-masing pada tingkat \(1-\alpha/m\), sehingga tingkat kepercayaan gabungannya sekurang-kurangnya \(1-\alpha\)."],
    [r"n=\left(\frac{z_{1-\alpha/2}\,\sigma}{E}\right)^2,\qquad \text{tingkat tiap selang}=1-\frac{\alpha}{m}"])],
  [(r"Berapa ukuran sampel agar galat batas selang 95% untuk rata-rata paling besar 0,5, bila \(\sigma\approx2\)?",
    r"\(n=(1{,}96\times2/0{,}5)^2=61{,}5\). Bulatkan ke atas: 62 pengamatan."),
   (r"Tiga selang kepercayaan dilaporkan bersama dengan tingkat kepercayaan gabungan 95%. Dengan koreksi Bonferroni, berapa tingkat kepercayaan tiap selang?",
    r"\(1-0{,}05/3=0{,}9833\), yaitu sekitar 98,3% per selang, sehingga ketiganya benar sekaligus dengan peluang sekurang-kurangnya 95%.")])

D("dasar-asumsi-residual",
  [(r"Pendalaman: residual tidak saling bebas dan tidak seragam ragamnya",
    [r"Walaupun galat \(\varepsilon_i\) saling bebas dengan ragam sama, residual \(e_i\) tidak. Dalam bentuk matriks, \(e=(I-H)y\) dengan matriks topi \(H=X(X^\top X)^{-1}X^\top\). Ragam residual ke-\(i\) adalah \(\sigma^2(1-h_{ii})\): pengamatan dengan pengungkit (leverage) besar punya residual yang lebih kecil ragamnya.",
     r"Karena itu residual mentah tidak sebanding satu sama lain. Residual terstudentkan membagi setiap residual dengan taksiran galat bakunya sendiri, sehingga dapat dibandingkan dengan sebaran t untuk mendeteksi pencilan; nilai di luar sekitar ±2 sampai ±3 patut diperiksa."],
    [r"e=(I-H)\,y,\qquad \operatorname{Var}(e_i)=\sigma^2(1-h_{ii}),\qquad r_i=\frac{e_i}{s\sqrt{1-h_{ii}}}"]),
   (r"Pendalaman: akibat pelanggaran asumsi",
    [r"Box (1954) menunjukkan bahwa ketidakhomogenan ragam berpengaruh kecil pada uji F bila ukuran kelompok sama, tetapi bisa besar bila tidak sama: bila kelompok kecil punya ragam besar, uji menjadi liberal (galat tipe I melebihi \(\alpha\)); bila kelompok besar punya ragam besar, uji menjadi konservatif.",
     r"Ketidakbebasan jauh lebih merusak. Dengan autokorelasi positif \(\rho\) antar pengamatan berurutan, ragam rata-rata sebenarnya kira-kira \(\frac{\sigma^2}{n}\cdot\frac{1+\rho}{1-\rho}\), sehingga galat baku yang mengabaikannya terlalu kecil dan P-value terlalu optimistis."],
    [r"\operatorname{Var}(\bar{y})\approx\frac{\sigma^2}{n}\cdot\frac{1+\rho}{1-\rho}\qquad(\text{AR(1)},\ n\ \text{besar})"])],
  [(r"Sebuah residual bernilai \(e=2{,}4\) dengan \(s=1{,}2\) dan pengungkit \(h=0{,}2\). Hitung residual terstudentkan internal. Apakah perlu diperiksa?",
    r"\(r=2{,}4/(1{,}2\sqrt{0{,}8})=2{,}24\). Nilainya di atas 2, sehingga pengamatan ini patut diperiksa, terutama bila juga berpengaruh besar (Cook's D tinggi)."),
   (r"Dari tiga asumsi galat (bebas, normal, ragam homogen), mana yang paling berbahaya bila dilanggar, dan mengapa?",
    r"Kebebasan. Pelanggaran normalitas ringan hampir tidak berpengaruh pada sampel cukup besar, dan ragam tidak homogen dapat ditangani (Welch, transformasi). Ketidakbebasan (misalnya pseudoreplikasi atau autokorelasi) membuat galat baku salah secara sistematis dan tidak dapat diperbaiki tanpa mengubah model.")])

D("dasar-prinsip-rancangan",
  [(r"Pendalaman: pengacakan sebagai dasar inferensi",
    [r"Pengacakan menjamin bahwa, secara rata-rata atas semua kemungkinan pengacakan, perbedaan bawaan antar satuan percobaan tidak memihak perlakuan mana pun. Dengan begitu penaksir efek perlakuan tak bias, dan galat percobaan menjadi taksiran sah bagi keragaman yang tidak dikendalikan.",
     r"Pengacakan juga membenarkan uji tanpa asumsi normal: uji permutasi (uji pengacakan) menghitung statistik untuk setiap kemungkinan penempatan perlakuan, lalu P-value adalah proporsi penempatan yang memberi statistik seekstrem atau lebih ekstrem dari yang teramati. Fisher menunjukkan bahwa uji F biasa adalah pendekatan yang baik bagi uji permutasi ini."],
    [r"\text{banyak pengacakan RAL}=\frac{(tr)!}{(r!)^t},\qquad P_{\text{permutasi}}=\frac{\#\{\text{pengacakan dengan }T^*\ge T_{\text{obs}}\}}{\#\{\text{semua pengacakan}\}}"]),
   (r"Pendalaman: efisiensi relatif pengelompokan",
    [r"Setelah RAK selesai dianalisis, kita dapat menaksir apakah pengelompokan bermanfaat, yaitu berapa kali lipat ulangan yang dibutuhkan RAL untuk ketelitian yang sama. Efisiensi relatif di atas 1 berarti pengelompokan efektif; misalnya 1,5 berarti RAL memerlukan 50% lebih banyak ulangan."],
    [r"ER=\frac{(r-1)\,KTK+r(t-1)\,KTG}{(rt-1)\,KTG}"])],
  [(r"Ada berapa cara mengacak 3 perlakuan dengan 2 ulangan ke 6 satuan percobaan pada RAL?",
    r"\(6!/(2!\,2!\,2!)=720/8=90\) cara. Uji permutasi eksak menghitung statistik untuk 90 penempatan ini."),
   (r"RAK dengan \(t=5\) perlakuan dan \(r=4\) kelompok memberi KTK \(=20\) dan KTG \(=5\). Hitung efisiensi relatif terhadap RAL.",
    r"\(ER=\frac{3(20)+4(4)(5)}{19(5)}=\frac{140}{95}=1{,}47\). Pengelompokan efektif: RAL memerlukan sekitar 47% lebih banyak ulangan untuk ketelitian yang sama.")])

D("dasar-anova",
  [(r"Pendalaman: ANOVA sebagai model linear",
    [r"Model \(y_{ij}=\mu+\tau_i+\varepsilon_{ij}\) dapat ditulis dalam bentuk matriks \(y=X\beta+\varepsilon\), dengan \(X\) berisi kolom 1 untuk \(\mu\) dan kolom indikator untuk tiap perlakuan. Matriks \(X\) ini tidak berpangkat penuh (kolom indikator berjumlah kolom 1), sehingga \(\mu\) dan \(\tau_i\) tidak dapat ditaksir sendiri-sendiri tanpa kendala, misalnya \(\sum\tau_i=0\).",
     r"Yang selalu dapat ditaksir (estimable) adalah rata-rata perlakuan \(\mu+\tau_i\) dan setiap kontras \(\sum c_i\tau_i\) dengan \(\sum c_i=0\). Itulah sebabnya kesimpulan ANOVA selalu dinyatakan dalam perbandingan antar perlakuan, bukan dalam nilai \(\tau_i\) secara mutlak."],
    [r"\hat{\mu}+\hat{\tau}_i=\bar{y}_{i\cdot},\qquad \widehat{\sum c_i\tau_i}=\sum c_i\bar{y}_{i\cdot}\quad\Big(\sum c_i=0\Big)"]),
   (r"Pendalaman: model tetap dan model acak",
    [r"Bila perlakuan dipilih secara sengaja dan kesimpulan hanya untuk perlakuan itu (misalnya tiga pupuk tertentu), modelnya tetap. Bila perlakuan adalah sampel acak dari populasi perlakuan (misalnya galur yang diambil acak dari koleksi), modelnya acak dan yang ditaksir adalah komponen ragam \(\sigma^2_\tau\).",
     r"Uji F untuk satu faktor sama pada kedua model, tetapi tafsirnya berbeda. Pada model acak, nilai harapan kuadrat tengah memberi penaksir komponen ragam, dan rasio komponen ragam perlakuan terhadap total adalah korelasi intrakelas (heritabilitas dalam konteks pemuliaan)."],
    [r"E(KTP)=\sigma^2+r\sigma^2_\tau,\quad E(KTG)=\sigma^2\ \Longrightarrow\ \hat{\sigma}^2_\tau=\frac{KTP-KTG}{r},\qquad \rho_I=\frac{\sigma^2_\tau}{\sigma^2_\tau+\sigma^2}"])],
  [(r"Sepuluh galur diambil acak dan ditanam dengan \(r=5\) ulangan. Diperoleh KTP \(=50\) dan KTG \(=10\). Taksir komponen ragam galur dan korelasi intrakelasnya.",
    r"\(\hat{\sigma}^2_\tau=(50-10)/5=8\). \(\rho_I=8/(8+10)=0{,}44\): sekitar 44% keragaman total berasal dari perbedaan antar galur."),
   (r"Pada model tetap dengan \(t=3\), \(r=4\), \(\sigma^2=1\), dan efek perlakuan \(\tau=(-2,0,2)\), berapa nilai harapan KTP?",
    r"\(E(KTP)=\sigma^2+\frac{r\sum\tau_i^2}{t-1}=1+\frac{4(8)}{2}=17\). Rasio harapan terhadap KTG sekitar 17, sehingga F yang teramati kemungkinan besar sangat nyata.")])

D("dasar-uji-lanjut",
  [(r"Pendalaman: BNT terlindung Fisher dan batasnya",
    [r"BNT terlindung (Fisher's protected LSD) hanya dijalankan bila uji F keseluruhan nyata. Perlindungan ini menjamin FWER \(\le\alpha\) bila semua rata-rata sebenarnya sama (hipotesis nol lengkap). Namun bila sebagian rata-rata sama dan sebagian berbeda, FWER untuk pasangan yang sebenarnya sama dapat melebihi \(\alpha\) ketika \(t\ge4\).",
     r"Karena itu BNT terlindung aman untuk tiga perlakuan, tetapi untuk empat perlakuan atau lebih uji yang mengendalikan FWER secara kuat (Tukey, Holm, Dunnett) lebih tepat."],
    []),
   (r"Pendalaman: tingkat penemuan palsu (FDR)",
    [r"Pada penelitian yang menguji sangat banyak hipotesis sekaligus (misalnya ratusan gen atau senyawa), mengendalikan FWER membuat hampir tidak ada yang nyata. Pendekatan alternatif mengendalikan tingkat penemuan palsu (false discovery rate, FDR), yaitu proporsi harapan hipotesis yang ditolak secara keliru di antara semua yang ditolak.",
     r"Prosedur Benjamini–Hochberg: urutkan P-value dari terkecil, cari \(k\) terbesar dengan \(p_{(k)}\le kq/m\), lalu tolak semua hipotesis ke-1 sampai ke-\(k\). Prosedur ini lebih kuat daripada Holm, dengan jaminan yang berbeda: ia membolehkan sebagian kecil penemuan palsu."],
    [r"FDR=E\!\left[\frac{V}{\max(R,1)}\right],\qquad k^*=\max\Big\{k:\ p_{(k)}\le\frac{k}{m}\,q\Big\}"])],
  [(r"Delapan uji memberi P-value terurut 0,001; 0,008; 0,039; 0,041; 0,042; 0,060; 0,074; 0,205. Terapkan Benjamini–Hochberg dengan \(q=0{,}05\).",
    r"Batas \(kq/m\): 0,00625; 0,0125; 0,01875; 0,025; 0,03125; 0,0375; 0,04375; 0,05. \(k\) terbesar dengan \(p_{(k)}\) di bawah batasnya adalah \(k=2\) (0,008 ≤ 0,0125). Dua hipotesis pertama ditolak."),
   (r"Dengan 10 perbandingan dan FWER 5%, berapa taraf uji tiap perbandingan menurut Bonferroni?",
    r"\(0{,}05/10=0{,}005\). Setiap perbandingan dinyatakan nyata hanya bila \(P<0{,}005\).")])

D("dasar-korelasi",
  [(r"Pendalaman: hubungan korelasi dan kemiringan regresi",
    [r"Kemiringan regresi \(Y\) atas \(X\) adalah korelasi yang diskalakan dengan rasio simpangan baku. Jadi korelasi dan kemiringan selalu bertanda sama, dan uji \(H_0:\rho=0\) setara dengan uji \(H_0:\beta_1=0\) pada regresi linear sederhana; keduanya memberi statistik t yang identik.",
     r"Perbedaannya: kemiringan bergantung pada satuan dan arah (regresi \(Y\) atas \(X\) berbeda dengan \(X\) atas \(Y\)), sedangkan korelasi simetris dan tanpa satuan."],
    [r"b_1=r\,\frac{s_y}{s_x},\qquad t=\frac{b_1}{SE(b_1)}=\frac{r\sqrt{n-2}}{\sqrt{1-r^2}}"]),
   (r"Pendalaman: pelemahan akibat galat pengukuran",
    [r"Bila \(X\) dan \(Y\) diukur dengan galat acak, korelasi yang teramati lebih kecil daripada korelasi sebenarnya. Besarnya pelemahan bergantung pada reliabilitas pengukuran (proporsi ragam teramati yang merupakan ragam sebenarnya). Rumus koreksi Spearman menaksir korelasi sebenarnya, tetapi hasilnya dapat melebihi 1 bila reliabilitas ditaksir terlalu rendah, jadi gunakan dengan hati-hati."],
    [r"r_{\text{teramati}}=\rho_{\text{sebenarnya}}\sqrt{\text{rel}_X\cdot\text{rel}_Y}"])],
  [(r"Diketahui \(r=0{,}8\), \(s_y=10\), dan \(s_x=4\). Berapa kemiringan regresi \(Y\) atas \(X\)?",
    r"\(b_1=0{,}8\times10/4=2{,}0\): setiap kenaikan satu satuan \(X\) diikuti kenaikan rata-rata 2 satuan \(Y\)."),
   (r"Korelasi sebenarnya antara dua sifat adalah 0,6, tetapi reliabilitas pengukurannya 0,8 dan 0,9. Berapa korelasi yang diperkirakan teramati?",
    r"\(0{,}6\sqrt{0{,}8\times0{,}9}=0{,}6\sqrt{0{,}72}=0{,}51\). Galat pengukuran menurunkan korelasi dari 0,60 menjadi sekitar 0,51.")])
